
local qbr=[==[]==]
local hsc=
(function(...)
local paln={57,211,230,125,188,244,80,116,89,175,45,75,74,41,66,238}
local jxyyi=bit32 or bit
local pz=jxyyi.bxor
for egzu=1,#paln do paln[egzu]=pz(paln[egzu],(73*egzu+216)%256) end
local imbs="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local kvhyt={}
for pny=1,#imbs do kvhyt[imbs:byte(pny)]=pny-1 end
local function wevh(str)
  local R={} local acc,nb=0,0
  for oal=1,#str do
    local v=kvhyt[str:byte(oal)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function aaoa(key,data)
  local S={} for gyorf=0,255 do S[gyorf]=gyorf end
  local j=0
  for rh=0,255 do
    j=(j+S[rh]+key[(rh%#key)+1])%256
    S[rh],S[j]=S[j],S[rh]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(pz(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=aaoa(paln,wevh(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local vd=nf()
return function(big) return vd(big) end
end)(...)

return hsc(qbr)
